    "Dual Nature of Radiation and Matter": [
      {
        "questionNumber": 1,
        "questionText": "The photoelectric effect demonstrates the:",
        "options": {
          "A": "Particle nature of light",
          "B": "Wave nature of light",
          "C": "Dual nature of light",
          "D": "Neither wave nor particle nature"
        },
        "correctAnswer": "A",
        "hint": "Think about what the photoelectric effect proves about light.",
        "solution": "The photoelectric effect can only be explained by considering light as consisting of photons (particles), hence it demonstrates the particle nature of light.",
        "difficulty": "Foundation"
      },
      {
        "questionNumber": 2,
        "questionText": "The minimum frequency below which no photoelectrons are emitted is called:",
        "options": {
          "A": "Threshold frequency",
          "B": "Cut-off frequency",
          "C": "Critical frequency",
          "D": "Both A and B"
        },
        "correctAnswer": "D",
        "hint": "Recall the terminology used for the minimum frequency.",
        "solution": "The minimum frequency required for photoelectric emission is called threshold frequency (also known as cut-off frequency), so both A and B are correct terms.",
        "difficulty": "Foundation"
      },
      {
        "questionNumber": 3,
        "questionText": "The work function of a metal is:",
        "options": {
          "A": "The energy of incident photons",
          "B": "The maximum energy of emitted electrons",
          "C": "The minimum energy required to eject an electron",
          "D": "The kinetic energy of electrons"
        },
        "correctAnswer": "C",
        "hint": "Definition of work function.",
        "solution": "Work function (φ₀) is the minimum energy required to just eject an electron from the metal surface.",
        "difficulty": "Foundation"
      },
      {
        "questionNumber": 4,
        "questionText": "In photoelectric effect, the stopping potential depends on:",
        "options": {
          "A": "Intensity of light",
          "B": "Neither",
          "C": "Both intensity and frequency",
          "D": "Frequency of light"
        },
        "correctAnswer": "D",
        "hint": "Stopping potential is related to maximum kinetic energy.",
        "solution": "Stopping potential V₀ depends on the maximum kinetic energy of photoelectrons, which depends on the frequency of incident light, not on intensity.",
        "difficulty": "Foundation"
      },
      {
        "questionNumber": 5,
        "questionText": "In photoelectric effect, the graph of stopping potential vs frequency is:",
        "options": {
          "A": "A straight line parallel to frequency axis",
          "B": "A parabola",
          "C": "A straight line with positive slope",
          "D": "An exponential curve"
        },
        "correctAnswer": "C",
        "hint": "eV₀ = hν - φ₀.",
        "solution": "V₀ = (h/e)ν - φ₀/e. This is a straight line with slope h/e.",
        "difficulty": "Intermediate"
      },
      {
        "questionNumber": 6,
        "questionText": "The work function of a metal is 4 eV. The longest wavelength that can cause photoelectric emission is:",
        "options": {
          "A": "5000 Å",
          "B": "4000 Å",
          "C": "2500 Å",
          "D": "3100 Å"
        },
        "correctAnswer": "D",
        "hint": "λ₀ = hc/φ₀.",
        "solution": "λ₀ = (6.63×10⁻³⁴ × 3×10⁸)/(4 × 1.6×10⁻¹⁹) = 19.89×10⁻²⁶/(6.4×10⁻¹⁹) ≈ 3.1×10⁻⁷ m = 3100 Å.",
        "difficulty": "Intermediate"
      },
      {
        "questionNumber": 7,
        "questionText": "The de Broglie wavelength of an electron with kinetic energy 120 eV is approximately:",
        "options": {
          "A": "1.12 Å",
          "B": "2.24 Å",
          "C": "0.56 Å",
          "D": "4.48 Å"
        },
        "correctAnswer": "A",
        "hint": "λ = 12.27/√V Å.",
        "solution": "λ = 12.27/√120 ≈ 12.27/10.95 ≈ 1.12 Å.",
        "difficulty": "Intermediate"
      },
      {
        "questionNumber": 8,
        "questionText": "The energy of a photon of wavelength 6000 Å is approximately:",
        "options": {
          "A": "1.24 eV",
          "B": "2.07 eV",
          "C": "3.1 eV",
          "D": "0.62 eV"
        },
        "correctAnswer": "B",
        "hint": "E = 12400/λ(Å) eV.",
        "solution": "E = 12400/6000 ≈ 2.07 eV.",
        "difficulty": "Intermediate"
      },
      {
        "questionNumber": 9,
        "questionText": "When a metallic surface is illuminated with radiation of wavelength λ, the stopping potential is V. If the same surface is illuminated with wavelength 2λ, the stopping potential is V/4. The threshold wavelength is:",
        "options": {
          "A": "3λ",
          "B": "4λ",
          "C": "5λ",
          "D": "5λ/2"
        },
        "correctAnswer": "A",
        "hint": "Use Einstein's photoelectric equation for both cases.",
        "solution": "eV = hc/λ - hc/λ₀; eV/4 = hc/(2λ) - hc/λ₀. Divide: 4 = \\[hc/λ - hc/λ₀] / \\[hc/(2λ) - hc/λ₀] = \\[1/λ - 1/λ₀] / \\[1/(2λ) - 1/λ₀]. 4\\[1/(2λ) - 1/λ₀] = 1/λ - 1/λ₀ → 2/λ - 4/λ₀ = 1/λ - 1/λ₀ → 1/λ = 3/λ₀ → λ₀ = 3λ.",
        "difficulty": "Advanced"
      },
      {
        "questionNumber": 10,
        "questionText": "The de Broglie wavelength of a neutron in thermal equilibrium with heavy water at temperature T is:",
        "options": {
          "A": "h/√(2mkT)",
          "B": "h/√(3mkT)",
          "C": "h/√(2πmkT)",
          "D": "√(3mkT)/h"
        },
        "correctAnswer": "B",
        "hint": "Thermal kinetic energy = (3/2)kT.",
        "solution": "K = (3/2)kT. λ = h/√(2mK) = h/√(3mkT).",
        "difficulty": "Advanced"
      }
    ],
